4534:pub fn create_module(vm: &mut Vm) -> Value {

// node:fs — the file-system module, modelled on the reference runtime's observable behaviour:
//
// * every operation is synchronous underneath; the callback API runs the sync operation inside a
//   `process.nextTick` callback and the promise API runs it immediately and returns a settled
//   promise;
// * errors embed Rust `io::Error` texts with a per-operation template (see the error helpers);
// * file descriptors come from a private table numbered from 0 (stdio is not part of it);
// * Stats/Dirent/Dir/FileHandle are small classes whose instances carry plain own properties;
// * ReadStream/WriteStream sit on a self-contained Readable/Writable base that mirrors the
//   reference stream semantics (state in `_readableState` / `_writableState`, writes serialised
//   through a promise chain).

use crate::builtins::typedarray::{ta_bytes, ta_values_vec};
use crate::object::*;
use crate::value::*;
use crate::vm::{Job, JsResult, Vm};
use std::cell::{Cell, RefCell};
use std::collections::{HashMap, VecDeque};
use std::io::{Read, Seek, SeekFrom, Write};
use std::os::unix::fs::{MetadataExt, PermissionsExt};

type IoResult<T> = std::io::Result<T>;

// ============================================================================================
// module state
// ============================================================================================

#[derive(Default, Clone)]
struct Classes {
    stats: Option<Obj>,
    dirent: Option<Obj>,
    dir: Option<Obj>,
    file_handle: Option<Obj>,
    read_stream: Option<Obj>,
    write_stream: Option<Obj>,
    stat_watcher: Option<Obj>,
    ee_proto: Option<Obj>,
    list_iter: Option<Obj>,
    dir_iter: Option<Obj>,
    readable_ctor: Option<Obj>,
    writable_ctor: Option<Obj>,
}

/// The internal Readable/Writable constructors the file streams are built on (a port of the
/// reference's stream base classes). Lets `node:stream` share them so that fs streams are
/// `instanceof stream.Readable/Writable`. Creates the fs module on first use.
#[allow(dead_code)]
pub fn stream_base_ctors(vm: &mut Vm) -> Option<(Obj, Obj)> {
    let _ = crate::runtime::node::builtin_module(vm, "fs");
    FS.with(|s| {
        let c = &s.borrow().classes;
        match (&c.readable_ctor, &c.writable_ctor) {
            (Some(r), Some(w)) => Some((r.clone(), w.clone())),
            _ => None,
        }
    })
}

struct Watch {
    path: String,
    watcher: Obj,
    listeners: Vec<Value>,
    prev: Value,
    timer: u64,
}

struct FsState {
    fds: HashMap<i64, std::fs::File>,
    next_fd: i64,
    tmp_counter: u32,
    classes: Classes,
    watchers: Vec<Watch>,
}

thread_local! {
    static FS: RefCell<FsState> = RefCell::new(FsState {
        fds: HashMap::new(),
        next_fd: 0,
        tmp_counter: 0,
        classes: Classes::default(),
        watchers: Vec::new(),
    });
}

fn class_proto(vm: &Vm, f: fn(&Classes) -> Option<Obj>) -> Obj {
    FS.with(|s| f(&s.borrow().classes)).unwrap_or_else(|| vm.intr.object_proto.clone())
}

// ============================================================================================
// small value helpers
// ============================================================================================

fn key(s: &str) -> PropKey {
    PropKey::from_str(s)
}

fn num_str(n: f64) -> String {
    crate::numconv::number_to_string(n)
}

/// `v.k` on any value (throws "cannot read property 'k' of undefined" on nullish bases).
fn getp(vm: &mut Vm, v: &Value, k: &str) -> JsResult<Value> {
    vm.get_prop_of(v, &key(k))
}

/// `v.k = x` (strict).
fn setp(vm: &mut Vm, v: &Value, k: &str, x: Value) -> JsResult<()> {
    vm.set_prop_of(v, key(k), x, true)
}

/// `options && options.k`
fn opt_get(vm: &mut Vm, opts: &Value, k: &str) -> JsResult<Value> {
    if opts.truthy() {
        getp(vm, opts, k)
    } else {
        Ok(opts.clone())
    }
}

fn to_num(vm: &mut Vm, v: &Value) -> JsResult<f64> {
    match v {
        Value::Num(n) => Ok(*n),
        Value::BigInt(b) => Ok(b.to_string_radix(10).parse::<f64>().unwrap_or(f64::NAN)),
        _ => vm.to_number(v),
    }
}

/// `this.m(...args)`
fn call_method(vm: &mut Vm, this: &Value, m: &str, args: &[Value]) -> JsResult<Value> {
    let f = getp(vm, this, m)?;
    if !f.is_callable() {
        return vm.throw_type(format!("(intermediate value).{} is not a function", m));
    }
    vm.call(&f, this.clone(), args)
}

fn emit(vm: &mut Vm, this: &Value, ev: &str, args: &[Value]) -> JsResult<Value> {
    let mut all = Vec::with_capacity(args.len() + 1);
    all.push(Value::str(ev));
    all.extend_from_slice(args);
    call_method(vm, this, "emit", &all)
}

/// Call a user callback the way the reference's arrow functions do (`cb(...)`).
fn call_cb(vm: &mut Vm, cb: &Value, args: &[Value]) -> JsResult<Value> {
    if !cb.is_callable() {
        return vm.throw_type("cb is not a function");
    }
    vm.call(cb, Value::Undefined, args)
}

fn closure(vm: &mut Vm, name: &str, len: u32, f: NativeFn, slots: Vec<Value>) -> Value {
    Value::Obj(vm.native_closure(name, len, f, slots))
}

/// process.nextTick(f)
fn next_tick(vm: &mut Vm, f: Value) -> JsResult<()> {
    if let Some(p) = vm.host.process_obj.clone() {
        let nt = vm.get_str(&p, "nextTick")?;
        if nt.is_callable() {
            vm.call(&nt, Value::Obj(p), &[f])?;
            return Ok(());
        }
    }
    vm.host.callbacks.push_back((f, Vec::new()));
    Ok(())
}

/// queueMicrotask(f) the reference way (a reaction on a resolved promise): same timing as a
/// plain microtask, but an exception surfaces as an unhandled rejection ("Uncaught (in promise)").
fn queue_microtask(vm: &mut Vm, f: Value) {
    match crate::builtins::promise::promise_resolve_intrinsic(vm, Value::Undefined) {
        Ok(p) => {
            let _ = crate::builtins::promise::promise_then(vm, &p, f, Value::Undefined);
        }
        Err(_) => vm.jobs.push_back(Job::Callback(f, Vec::new())),
    }
}

fn resolved(vm: &mut Vm, v: Value) -> Value {
    let cap = vm.new_promise_capability_intrinsic();
    let _ = vm.call(&cap.resolve, Value::Undefined, &[v]);
    cap.promise
}

fn rejected(vm: &mut Vm, e: Value) -> Value {
    let cap = vm.new_promise_capability_intrinsic();
    let _ = vm.call(&cap.reject, Value::Undefined, &[e]);
    cap.promise
}

/// promisedCall: the operation already ran; settle a fresh promise with its outcome.
fn settle(vm: &mut Vm, r: JsResult<Value>) -> Value {
    match r {
        Ok(v) => resolved(vm, v),
        Err(e) => rejected(vm, e),
    }
}

fn iter_result(vm: &mut Vm, v: Value, done: bool) -> Value {
    Value::Obj(vm.obj_from(vec![("value", v), ("done", Value::Bool(done))]))
}

fn new_date(vm: &mut Vm, t: f64) -> Value {
    Value::Obj(Obj::with_class(Some(vm.intr.date_proto.clone()), ObjKind::Date(crate::datetime::time_clip(t)), "Date"))
}

/// `new Date(v)` for a single argument.
fn date_from_value(vm: &mut Vm, v: &Value) -> JsResult<Value> {
    let t = match v {
        Value::Num(n) => *n,
        Value::Obj(o) if matches!(o.borrow().kind, ObjKind::Date(_)) => match &o.borrow().kind {
            ObjKind::Date(t) => *t,
            _ => f64::NAN,
        },
        _ => {
            let p = vm.to_primitive(v, crate::ops::Hint::Default)?;
            match &p {
                Value::Str(s) => crate::datetime::parse_for_constructor(&s.to_rust_string()),
                _ => vm.to_number(&p)?,
            }
        }
    };
    Ok(new_date(vm, t))
}

/// Run `f` with the reference's JS frames (outermost first) on the trace, so errors created
/// inside carry the same `stack` lines. The reference engine has proper tail calls, so only
/// frames that are still live at the throw site are listed by the callers of this helper.
fn with_frames<T>(vm: &mut Vm, names: &[&str], f: impl FnOnce(&mut Vm) -> JsResult<T>) -> JsResult<T> {
    for n in names {
        vm.trace.push(crate::vm::TraceEntry { name: JsStr::from_str(n) });
    }
    let r = f(vm);
    let keep = vm.trace.len().saturating_sub(names.len());
    vm.trace.truncate(keep);
    r
}

/// A native whose JS counterpart's frame(s) are live while it runs.
macro_rules! framed {
    ($name:ident, [$($frame:expr),*], $inner:ident) => {
        fn $name(vm: &mut Vm, a: &Args) -> JsResult<Value> {
            with_frames(vm, &[$($frame),*], |vm| $inner(vm, a))
        }
    };
    ($name:ident, $frame:expr, $inner:ident) => {
        fn $name(vm: &mut Vm, a: &Args) -> JsResult<Value> {
            with_frames(vm, &[$frame], |vm| $inner(vm, a))
        }
    };
}

fn require_new(vm: &mut Vm, a: &Args) -> JsResult<Obj> {
    match &a.new_target {
        Some(nt) => Ok(nt.clone()),
        None => vm.throw_type("Class constructor cannot be invoked without 'new'"),
    }
}

}

// ============================================================================================
// streams: self-contained Readable / Writable bases
// ============================================================================================

fn state_of(vm: &mut Vm, this: &Value, which: &str) -> JsResult<Value> {
    getp(vm, this, which)
}

fn rstate(vm: &mut Vm, this: &Value) -> JsResult<Value> {
    state_of(vm, this, "_readableState")
}

fn wstate(vm: &mut Vm, this: &Value) -> JsResult<Value> {
    state_of(vm, this, "_writableState")
}

fn sget(vm: &mut Vm, st: &Value, k: &str) -> JsResult<Value> {
    getp(vm, st, k)
}

fn snum(vm: &mut Vm, st: &Value, k: &str) -> JsResult<f64> {
    let v = getp(vm, st, k)?;
    to_num(vm, &v)
}

fn sset(vm: &mut Vm, st: &Value, k: &str, v: Value) -> JsResult<()> {
    setp(vm, st, k, v)
}

fn default_hwm(object_mode: bool) -> f64 {
    if object_mode {
        16.0
    } else {
        65536.0
    }
}

fn array_len(vm: &mut Vm, arr: &Value) -> JsResult<f64> {
    let l = getp(vm, arr, "length")?;
    to_num(vm, &l)
}

fn chunk_len(vm: &mut Vm, chunk: &Value) -> JsResult<f64> {
    let l = getp(vm, chunk, "length")?;
    to_num(vm, &l)
}

/// Readable constructor body (`super(opts)` for ReadStream).
fn readable_init(vm: &mut Vm, o: &Obj, opts: &Value) -> JsResult<()> {
    crate::runtime::events::init_emitter(vm, o);
    let this = Value::Obj(o.clone());
    let om = getp(vm, opts, "objectMode")?.truthy() || getp(vm, opts, "readableObjectMode")?.truthy();
    let hwm = getp(vm, opts, "highWaterMark")?;
    let hwm = if hwm.is_undefined() { Value::Num(default_hwm(om)) } else { Value::Num(to_num(vm, &hwm)?) };
    let buffer = Value::Obj(vm.new_array(Vec::new()));
    let st = vm.obj_from(vec![
        ("flowing", Value::Null),
        ("ended", Value::Bool(false)),
        ("endEmitted", Value::Bool(false)),
        ("buffer", buffer),
        ("length", Value::Num(0.0)),
        ("objectMode", Value::Bool(om)),
        ("highWaterMark", hwm),
        ("encoding", Value::Null),
        ("destroyed", Value::Bool(false)),
        ("reading", Value::Bool(false)),
        ("errored", Value::Null),
    ]);
    setp(vm, &this, "_readableState", Value::Obj(st))?;
    setp(vm, &this, "readable", Value::Bool(true))?;
    let enc = getp(vm, opts, "encoding")?;
    if enc.truthy() {
        call_method(vm, &this, "setEncoding", &[enc])?;
    }
    let read = getp(vm, opts, "read")?;
    if read.is_callable() {
        setp(vm, &this, "_read", read)?;
    }
    Ok(())
}

fn stream_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nt = require_new(vm, a)?;
    let fb = vm.intr.object_proto.clone();
    let proto = vm.proto_from_nt(&Some(nt), &fb)?;
    let o = Obj::new(Some(proto), ObjKind::Ordinary);
    crate::runtime::events::init_emitter(vm, &o);
    Ok(Value::Obj(o))
}

fn readable_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nt = require_new(vm, a)?;
    let fb = vm.intr.object_proto.clone();
    let proto = vm.proto_from_nt(&Some(nt), &fb)?;
    let o = Obj::new(Some(proto), ObjKind::Ordinary);
    let opts = if a.arg(0).is_undefined() { Value::Obj(vm.new_object()) } else { a.arg(0) };
    readable_init(vm, &o, &opts)?;
    Ok(Value::Obj(o))
}

fn maybe_emit_end(vm: &mut Vm, this: &Value) -> JsResult<()> {
    let st = rstate(vm, this)?;
    let ended = sget(vm, &st, "ended")?.truthy();
    let emitted = sget(vm, &st, "endEmitted")?.truthy();
    let len = snum(vm, &st, "length")?;
    let flowing = sget(vm, &st, "flowing")?;
    if ended && !emitted && len == 0.0 && !matches!(flowing, Value::Bool(false)) {
        sset(vm, &st, "endEmitted", Value::Bool(true))?;
        sset(vm, &st, "flowing", Value::Bool(false))?;
        let f = closure(vm, "", 0, emit_end_job, vec![this.clone()]);
        queue_microtask(vm, f);
    }
    Ok(())
}

fn emit_end_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "end", &[])?;
    Ok(Value::Undefined)
}

fn flow_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    flow(vm, a.slot(0))?;
    Ok(Value::Undefined)
}

fn flow(vm: &mut Vm, this: Value) -> JsResult<()> {
    let st = rstate(vm, &this)?;
    loop {
        let flowing = sget(vm, &st, "flowing")?.truthy();
        let buf = sget(vm, &st, "buffer")?;
        if !flowing || array_len(vm, &buf)? == 0.0 {
            break;
        }
        let chunk = call_method(vm, &buf, "shift", &[])?;
        let om = sget(vm, &st, "objectMode")?.truthy();
        let l = if om { 1.0 } else { chunk_len(vm, &chunk)? };
        let cur = snum(vm, &st, "length")?;
        sset(vm, &st, "length", Value::Num(cur - l))?;
        emit(vm, &this, "data", &[chunk])?;
    }
    maybe_emit_end(vm, &this)
}

fn readable_push(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let st = rstate(vm, &this)?;
    let mut chunk = a.arg(0);
    if chunk.is_null() {
        sset(vm, &st, "ended", Value::Bool(true))?;
        maybe_emit_end(vm, &this)?;
        return Ok(Value::Bool(false));
    }
    if sget(vm, &st, "destroyed")?.truthy() {
        return Ok(Value::Bool(false));
    }
    let enc = sget(vm, &st, "encoding")?;
    if enc.truthy() {
        let bytes = match &chunk {
            Value::Obj(o) if matches!(&o.borrow().kind, ObjKind::TypedArray(t) if t.kind == TAKind::Uint8) => Some(ta_bytes(o)),
            _ => None,
        };
        if let Some(b) = bytes {
            chunk = bytes_to_string(vm, &b, &enc)?;
        }
    }
    if sget(vm, &st, "flowing")?.truthy() {
        emit(vm, &this, "data", &[chunk])?;
    } else {
        let buf = sget(vm, &st, "buffer")?;
        call_method(vm, &buf, "push", &[chunk.clone()])?;
        let om = sget(vm, &st, "objectMode")?.truthy();
        let l = if om { 1.0 } else { chunk_len(vm, &chunk)? };
        let cur = snum(vm, &st, "length")?;
        sset(vm, &st, "length", Value::Num(cur + l))?;
        emit(vm, &this, "readable", &[])?;
    }
    let len = snum(vm, &st, "length")?;
    let hwm = snum(vm, &st, "highWaterMark")?;
    Ok(Value::Bool(len < hwm))
}

fn readable_read(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let st = rstate(vm, &this)?;
    let buf = sget(vm, &st, "buffer")?;
    if sget(vm, &st, "objectMode")?.truthy() {
        if array_len(vm, &buf)? == 0.0 {
            return Ok(Value::Null);
        }
        let cur = snum(vm, &st, "length")?;
        sset(vm, &st, "length", Value::Num(cur - 1.0))?;
        let v = call_method(vm, &buf, "shift", &[])?;
        maybe_emit_end(vm, &this)?;
        return Ok(v);
    }
    let size = a.arg(0);
    let mut wanted = if size.is_nullish() { snum(vm, &st, "length")? } else { to_num(vm, &size)? };
    if !(wanted.is_finite() && wanted.fract() == 0.0) || wanted < 0.0 {
        return vm.throw_range("The value of size is out of range");
    }
    if wanted == 0.0 {
        maybe_emit_end(vm, &this)?;
        return Ok(Value::Null);
    }
    let len = snum(vm, &st, "length")?;
    if len < wanted {
        if !sget(vm, &st, "ended")?.truthy() {
            return Ok(Value::Null);
        }
        wanted = len;
    }
    if array_len(vm, &buf)? == 0.0 {
        return Ok(Value::Null);
    }
    let mut chunks = Vec::new();
    let mut remaining = wanted;
    while remaining > 0.0 && array_len(vm, &buf)? > 0.0 {
        let first = vm.get_elem(&buf, &Value::Num(0.0))?;
        let cl = chunk_len(vm, &first)?;
        if cl <= remaining {
            let c = call_method(vm, &buf, "shift", &[])?;
            chunks.push(c);
            remaining -= cl;
        } else {
            let head = call_method(vm, &first, "slice", &[Value::Num(0.0), Value::Num(remaining)])?;
            chunks.push(head);
            let tail = call_method(vm, &first, "slice", &[Value::Num(remaining)])?;
            vm.set_elem(&buf, &Value::Num(0.0), tail, true)?;
            remaining = 0.0;
        }
    }
    let cur = snum(vm, &st, "length")?;
    sset(vm, &st, "length", Value::Num(cur - wanted))?;
    let enc = sget(vm, &st, "encoding")?;
    let out = if enc.truthy() {
        let mut s = JsStr::from_str("");
        for c in &chunks {
            let cs = vm.to_string(c)?;
            s = JsStr::concat(&s, &cs);
        }
        Value::Str(s)
    } else {
        let mut bytes = Vec::new();
        for c in &chunks {
            let b = to_buffer(vm, c, &Value::Undefined)?;
            bytes.extend_from_slice(&b);
        }
        bytes.truncate(wanted as usize);
        new_buffer(vm, bytes)?
    };
    maybe_emit_end(vm, &this)?;
    Ok(out)
}

fn readable_set_encoding(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    let s = string_of(vm, &a.arg(0))?.to_lowercase().replacen('-', "", 1);
    sset(vm, &st, "encoding", Value::str(&s))?;
    Ok(a.this.clone())
}

fn ee_method(vm: &mut Vm, name: &str) -> JsResult<Value> {
    let p = class_proto(vm, |c| c.ee_proto.clone());
    vm.get_str(&p, name)
}

fn is_data_event(v: &Value) -> bool {
    matches!(v, Value::Str(s) if s.eq_str("data"))
}

fn readable_on(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let on = ee_method(vm, "on")?;
    let res = vm.call(&on, a.this.clone(), &[a.arg(0), a.arg(1)])?;
    if is_data_event(&a.arg(0)) {
        let st = rstate(vm, &a.this)?;
        if !matches!(sget(vm, &st, "flowing")?, Value::Bool(false)) {
            call_method(vm, &a.this, "resume", &[])?;
        }
    }
    Ok(res)
}

fn readable_add_listener(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    call_method(vm, &a.this, "on", &[a.arg(0), a.arg(1)])
}

fn readable_once(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let once = ee_method(vm, "once")?;
    let res = vm.call(&once, a.this.clone(), &[a.arg(0), a.arg(1)])?;
    if is_data_event(&a.arg(0)) {
        let st = rstate(vm, &a.this)?;
        if !matches!(sget(vm, &st, "flowing")?, Value::Bool(false)) {
            call_method(vm, &a.this, "resume", &[])?;
        }
    }
    Ok(res)
}

fn readable_resume(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    if sget(vm, &st, "flowing")?.truthy() {
        return Ok(a.this.clone());
    }
    sset(vm, &st, "flowing", Value::Bool(true))?;
    let f = closure(vm, "", 0, flow_job, vec![a.this.clone()]);
    queue_microtask(vm, f);
    Ok(a.this.clone())
}

fn readable_pause(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    sset(vm, &st, "flowing", Value::Bool(false))?;
    Ok(a.this.clone())
}

fn readable_is_paused(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    Ok(Value::Bool(matches!(sget(vm, &st, "flowing")?, Value::Bool(false))))
}

fn readable_pipe(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let dest = a.arg(0);
    let opts = if a.arg(1).is_undefined() { Value::Obj(vm.new_object()) } else { a.arg(1) };
    let ondata = closure(vm, "", 1, pipe_on_data, vec![this.clone(), dest.clone()]);
    call_method(vm, &this, "on", &[Value::str("data"), ondata])?;
    let end = getp(vm, &opts, "end")?;
    if !matches!(end, Value::Bool(false)) {
        let onend = closure(vm, "", 0, pipe_on_end, vec![dest.clone()]);
        call_method(vm, &this, "on", &[Value::str("end"), onend])?;
    }
    let onerr = closure(vm, "", 1, pipe_on_error, vec![dest.clone()]);
    call_method(vm, &this, "on", &[Value::str("error"), onerr])?;
    if getp(vm, &dest, "emit")?.truthy() {
        emit(vm, &dest, "pipe", &[this])?;
    }
    Ok(dest)
}

fn pipe_on_data(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (src, dest) = (a.slot(0), a.slot(1));
    let ok = call_method(vm, &dest, "write", &[a.arg(0)])?;
    if matches!(ok, Value::Bool(false)) && getp(vm, &src, "pause")?.is_callable() {
        call_method(vm, &src, "pause", &[])?;
        let resume = closure(vm, "", 0, pipe_resume, vec![src]);
        call_method(vm, &dest, "once", &[Value::str("drain"), resume])?;
    }
    Ok(Value::Undefined)
}

fn pipe_resume(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    call_method(vm, &a.slot(0), "resume", &[])
}

fn pipe_on_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    call_method(vm, &a.slot(0), "end", &[])
}

fn pipe_on_error(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let dest = a.slot(0);
    if getp(vm, &dest, "destroy")?.truthy() {
        call_method(vm, &dest, "destroy", &[a.arg(0)])?;
    }
    Ok(Value::Undefined)
}

fn readable_unpipe(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    call_method(vm, &a.this, "pause", &[])?;
    Ok(a.this.clone())
}

fn destroy_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let err = a.slot(1);
    if err.truthy() {
        emit(vm, &this, "error", &[err])?;
    }
    emit(vm, &this, "close", &[])?;
    Ok(Value::Undefined)
}

fn readable_destroy(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let st = rstate(vm, &this)?;
    if sget(vm, &st, "destroyed")?.truthy() {
        return Ok(this);
    }
    sset(vm, &st, "destroyed", Value::Bool(true))?;
    let err = a.arg(0);
    if err.truthy() {
        sset(vm, &st, "errored", err.clone())?;
        let ws = getp(vm, &this, "_writableState")?;
        if ws.truthy() {
            sset(vm, &ws, "errored", err.clone())?;
        }
    }
    setp(vm, &this, "readable", Value::Bool(false))?;
    let job = closure(vm, "", 0, destroy_job, vec![this.clone(), err]);
    queue_microtask(vm, job);
    Ok(this)
}

fn readable_length(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    sget(vm, &st, "length")
}

fn readable_hwm(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    sget(vm, &st, "highWaterMark")
}

fn readable_object_mode(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = rstate(vm, &a.this)?;
    sget(vm, &st, "objectMode")
}

// --- Readable[Symbol.asyncIterator] ---

struct RIter {
    queue: RefCell<VecDeque<Value>>,
    done: Cell<bool>,
    error: RefCell<Option<Value>>,
    pending: RefCell<Option<(Value, Value)>>,
}

fn riter<R>(v: &Value, f: impl FnOnce(&RIter) -> R) -> Option<R> {
    match v {
        Value::Obj(o) => match &o.borrow().kind {
            ObjKind::Host(h) => h.downcast_ref::<RIter>().map(f),
            _ => None,
        },
        _ => None,
    }
}

fn riter_settle(vm: &mut Vm, st: &Value) -> JsResult<()> {
    let pending = riter(st, |s| s.pending.borrow().clone()).flatten();
    let (res, rej) = match pending {
        Some(p) => p,
        None => return Ok(()),
    };
    let err = riter(st, |s| s.error.borrow().clone()).flatten();
    if let Some(e) = err {
        riter(st, |s| *s.pending.borrow_mut() = None);
        vm.call(&rej, Value::Undefined, &[e])?;
        return Ok(());
    }
    let item = riter(st, |s| s.queue.borrow_mut().pop_front()).flatten();
    if let Some(v) = item {
        riter(st, |s| *s.pending.borrow_mut() = None);
        let r = iter_result(vm, v, false);
        vm.call(&res, Value::Undefined, &[r])?;
        return Ok(());
    }
    if riter(st, |s| s.done.get()).unwrap_or(false) {
        riter(st, |s| *s.pending.borrow_mut() = None);
        let r = iter_result(vm, Value::Undefined, true);
        vm.call(&res, Value::Undefined, &[r])?;
    }
    Ok(())
}

fn riter_on_data(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = a.slot(0);
    let c = a.arg(0);
    riter(&st, |s| s.queue.borrow_mut().push_back(c));
    riter_settle(vm, &st)?;
    Ok(Value::Undefined)
}

fn riter_on_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = a.slot(0);
    riter(&st, |s| s.done.set(true));
    riter_settle(vm, &st)?;
    Ok(Value::Undefined)
}

fn riter_on_error(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = a.slot(0);
    let e = a.arg(0);
    riter(&st, |s| *s.error.borrow_mut() = Some(e));
    riter_settle(vm, &st)?;
    Ok(Value::Undefined)
}

fn riter_next(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = a.slot(0);
    if let Some(v) = riter(&st, |s| s.queue.borrow_mut().pop_front()).flatten() {
        let r = iter_result(vm, v, false);
        return Ok(resolved(vm, r));
    }
    if let Some(e) = riter(&st, |s| s.error.borrow().clone()).flatten() {
        return Ok(rejected(vm, e));
    }
    if riter(&st, |s| s.done.get()).unwrap_or(false) {
        let r = iter_result(vm, Value::Undefined, true);
        return Ok(resolved(vm, r));
    }
    let cap = vm.new_promise_capability_intrinsic();
    riter(&st, |s| *s.pending.borrow_mut() = Some((cap.resolve.clone(), cap.reject.clone())));
    Ok(cap.promise)
}

fn riter_return(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    call_method(vm, &a.slot(1), "destroy", &[])?;
    let r = iter_result(vm, Value::Undefined, true);
    Ok(resolved(vm, r))
}

fn return_this(_vm: &mut Vm, a: &Args) -> JsResult<Value> {
    Ok(a.this.clone())
}

fn readable_async_iterator(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let st = Value::Obj(Obj::new(None, ObjKind::Host(Box::new(RIter { queue: RefCell::new(VecDeque::new()), done: Cell::new(false), error: RefCell::new(None), pending: RefCell::new(None) }))));
    let ondata = closure(vm, "", 1, riter_on_data, vec![st.clone()]);
    call_method(vm, &this, "on", &[Value::str("data"), ondata])?;
    let onend = closure(vm, "", 0, riter_on_end, vec![st.clone()]);
    call_method(vm, &this, "on", &[Value::str("end"), onend])?;
    let onerr = closure(vm, "", 1, riter_on_error, vec![st.clone()]);
    call_method(vm, &this, "on", &[Value::str("error"), onerr])?;
    let it = vm.new_object();
    let next = vm.native_closure("next", 0, riter_next, vec![st.clone(), this.clone()]);
    it.set_prop(key("next"), Value::Obj(next), WEC);
    let ret = vm.native_closure("return", 0, riter_return, vec![st, this]);
    it.set_prop(key("return"), Value::Obj(ret), WEC);
    let ai = vm.native_fn("[Symbol.asyncIterator]", 0, return_this);
    it.set_prop(PropKey::Sym(vm.intr.sym_async_iterator.clone()), Value::Obj(ai), WEC);
    Ok(Value::Obj(it))
}

// --- Writable ---

fn writable_init(vm: &mut Vm, o: &Obj, opts: &Value) -> JsResult<()> {
    crate::runtime::events::init_emitter(vm, o);
    let this = Value::Obj(o.clone());
    let om = getp(vm, opts, "objectMode")?.truthy() || getp(vm, opts, "writableObjectMode")?.truthy();

// --- Writable ---

fn writable_init(vm: &mut Vm, o: &Obj, opts: &Value) -> JsResult<()> {
    crate::runtime::events::init_emitter(vm, o);
    let this = Value::Obj(o.clone());
    let om = getp(vm, opts, "objectMode")?.truthy() || getp(vm, opts, "writableObjectMode")?.truthy();
    let hwm = getp(vm, opts, "highWaterMark")?;
    let hwm = if hwm.is_undefined() { Value::Num(default_hwm(om)) } else { Value::Num(to_num(vm, &hwm)?) };
    let cork = Value::Obj(vm.new_array(Vec::new()));
    let tail = resolved(vm, Value::Undefined);
    let st = vm.obj_from(vec![
        ("ended", Value::Bool(false)),
        ("finished", Value::Bool(false)),
        ("destroyed", Value::Bool(false)),
        ("corked", Value::Num(0.0)),
        ("corkBuffer", cork),
        ("errored", Value::Null),
        ("tail", tail),
        ("objectMode", Value::Bool(om)),
        ("highWaterMark", hwm),
        ("length", Value::Num(0.0)),
        ("needDrain", Value::Bool(false)),
    ]);
    setp(vm, &this, "_writableState", Value::Obj(st))?;
    setp(vm, &this, "writable", Value::Bool(true))?;
    for (opt, prop) in [("write", "_write"), ("writev", "_writev"), ("final", "_final")] {
        let f = getp(vm, opts, opt)?;
        if f.is_callable() {
            setp(vm, &this, prop, f)?;
        }
    }
    Ok(())
}

fn writable_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let nt = require_new(vm, a)?;
    let fb = vm.intr.object_proto.clone();
    let proto = vm.proto_from_nt(&Some(nt), &fb)?;
    let o = Obj::new(Some(proto), ObjKind::Ordinary);
    let opts = if a.arg(0).is_undefined() { Value::Obj(vm.new_object()) } else { a.arg(0) };
    writable_init(vm, &o, &opts)?;
    Ok(Value::Obj(o))
}

fn writable_default_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    vm.call(&a.arg(2), Value::Undefined, &[])
}

fn then_on(vm: &mut Vm, p: &Value, f: Value) -> JsResult<Value> {
    match p {
        Value::Obj(po) if crate::builtins::promise::is_promise(p) => crate::builtins::promise::promise_then(vm, po, f, Value::Undefined),
        _ => call_method(vm, p, "then", &[f]),
    }
}

/// state.tail = state.tail.then(() => new Promise(resolve => stream._write(chunk, enc, err => { completeWrite(...); resolve(); })))
fn queue_write(vm: &mut Vm, this: &Value, entry: &Value) -> JsResult<()> {
    let st = wstate(vm, this)?;
    let tail = sget(vm, &st, "tail")?;
    let h = closure(vm, "", 0, write_job, vec![this.clone(), entry.clone()]);
    let nt = then_on(vm, &tail, h)?;
    sset(vm, &st, "tail", nt)
}

fn write_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, entry) = (a.slot(0), a.slot(1));
    let cap = vm.new_promise_capability_intrinsic();
    let done = closure(vm, "", 1, write_done, vec![this.clone(), entry.clone(), cap.resolve.clone()]);
    let chunk = getp(vm, &entry, "chunk")?;
    let enc = getp(vm, &entry, "encoding")?;
    if let Err(e) = call_method(vm, &this, "_write", &[chunk, enc, done]) {
        vm.call(&cap.reject, Value::Undefined, &[e])?;
    }
    Ok(cap.promise)
}

fn write_done(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    complete_write(vm, &a.slot(0), &a.slot(1), &a.arg(0))?;
    vm.call(&a.slot(2), Value::Undefined, &[])?;
    Ok(Value::Undefined)
}

fn complete_write(vm: &mut Vm, this: &Value, entry: &Value, err: &Value) -> JsResult<()> {
    let st = wstate(vm, this)?;
    let l = getp(vm, entry, "length")?;
    let l = to_num(vm, &l)?;
    let cur = snum(vm, &st, "length")?;
    sset(vm, &st, "length", Value::Num(cur - l))?;
    if err.truthy() {
        emit(vm, this, "error", &[err.clone()])?;
    }
    let cb = getp(vm, entry, "cb")?;
    if cb.truthy() {
        vm.call(&cb, Value::Undefined, &[err.clone()])?;
    }
    if sget(vm, &st, "needDrain")?.truthy() {
        let len = snum(vm, &st, "length")?;
        let hwm = snum(vm, &st, "highWaterMark")?;
        if len < hwm {
            sset(vm, &st, "needDrain", Value::Bool(false))?;
            let f = closure(vm, "", 0, emit_drain_job, vec![this.clone()]);
            queue_microtask(vm, f);
        }
    }
    Ok(())
}

fn emit_drain_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "drain", &[])?;
    Ok(Value::Undefined)
}

fn write_after_end_cb(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    vm.call(&a.slot(0), Value::Undefined, &[a.slot(1)])
}

fn writable_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let chunk = a.arg(0);
    let (mut enc, mut cb) = (a.arg(1), a.arg(2));
    if enc.is_callable() {
        cb = enc;
        enc = Value::Null;
    }
    let st = wstate(vm, &this)?;
    if sget(vm, &st, "ended")?.truthy() {
        let err = plain_err(vm, "write after end");
        if cb.truthy() {
            let f = closure(vm, "", 0, write_after_end_cb, vec![cb, err]);
            queue_microtask(vm, f);
        } else {
            emit(vm, &this, "error", &[err])?;
        }
        return Ok(Value::Bool(false));
    }
    let length = if sget(vm, &st, "objectMode")?.truthy() {
        1.0
    } else {
        let l = if chunk.truthy() { getp(vm, &chunk, "length")? } else { Value::Undefined };
        if !l.is_undefined() {
            to_num(vm, &l)?
        } else {
            let s = string_of(vm, &chunk)?;
            let e = match &enc {
                Value::Str(x) => crate::runtime::buffer::norm_encoding(&x.to_rust_string()).unwrap_or("utf8"),
                _ => "utf8",
            };
            crate::runtime::buffer::encode_string(&JsStr::from_str(&s), e).len() as f64
        }
    };
    let cur = snum(vm, &st, "length")?;
    sset(vm, &st, "length", Value::Num(cur + length))?;
    let entry = Value::Obj(vm.obj_from(vec![("chunk", chunk), ("encoding", enc), ("cb", cb), ("length", Value::Num(length))]));
    if snum(vm, &st, "corked")? != 0.0 && sget(vm, &st, "corked")?.truthy() {
        let cbuf = sget(vm, &st, "corkBuffer")?;
        call_method(vm, &cbuf, "push", &[entry])?;
    } else {
        queue_write(vm, &this, &entry)?;
    }
    let len = snum(vm, &st, "length")?;
    let hwm = snum(vm, &st, "highWaterMark")?;
    if len >= hwm {
        sset(vm, &st, "needDrain", Value::Bool(true))?;
    }
    Ok(Value::Bool(!sget(vm, &st, "needDrain")?.truthy()))
}

fn writable_queue_batch(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let entries = a.arg(0);
    let list = crate::builtins::array::array_like_to_vec(vm, &entries)?;
    let writev = getp(vm, &this, "_writev")?;
    if list.len() > 1 && writev.is_callable() {
        let st = wstate(vm, &this)?;
        let tail = sget(vm, &st, "tail")?;
        let h = closure(vm, "", 0, writev_job, vec![this.clone(), entries.clone()]);
        let nt = then_on(vm, &tail, h)?;
        sset(vm, &st, "tail", nt)?;
    } else {
        for e in list {
            queue_write(vm, &this, &e)?;
        }
    }
    Ok(Value::Undefined)
}

fn writev_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, entries) = (a.slot(0), a.slot(1));
    let cap = vm.new_promise_capability_intrinsic();
    let list = crate::builtins::array::array_like_to_vec(vm, &entries)?;
    let mut chunks = Vec::new();
    for e in &list {
        let c = getp(vm, e, "chunk")?;
        let en = getp(vm, e, "encoding")?;
        chunks.push(Value::Obj(vm.obj_from(vec![("chunk", c), ("encoding", en)])));
    }
    let arr = Value::Obj(vm.new_array(chunks));
    let done = closure(vm, "", 1, writev_done, vec![this.clone(), entries, cap.resolve.clone()]);
    if let Err(e) = call_method(vm, &this, "_writev", &[arr, done]) {
        vm.call(&cap.reject, Value::Undefined, &[e])?;
    }
    Ok(cap.promise)
}

fn writev_done(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let list = crate::builtins::array::array_like_to_vec(vm, &a.slot(1))?;
    for e in list {
        complete_write(vm, &this, &e, &a.arg(0))?;
    }
    vm.call(&a.slot(2), Value::Undefined, &[])?;
    Ok(Value::Undefined)
}

fn writable_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let (mut chunk, mut enc, mut cb) = (a.arg(0), a.arg(1), a.arg(2));
    if chunk.is_callable() {
        cb = chunk;
        chunk = Value::Null;
    } else if enc.is_callable() {
        cb = enc;
        enc = Value::Null;
    }
    let st = wstate(vm, &this)?;
    if !chunk.is_nullish() {
        call_method(vm, &this, "write", &[chunk, enc])?;
    }
    sset(vm, &st, "ended", Value::Bool(true))?;
    if sget(vm, &st, "corked")?.truthy() {
        sset(vm, &st, "corked", Value::Num(0.0))?;
        let cbuf = sget(vm, &st, "corkBuffer")?;
        let entries = call_method(vm, &cbuf, "splice", &[Value::Num(0.0)])?;
        call_method(vm, &this, "_queueBatch", &[entries])?;
    }
    let tail = sget(vm, &st, "tail")?;
    let h = closure(vm, "", 0, end_job, vec![this.clone(), cb]);
    then_on(vm, &tail, h)?;
    Ok(this)
}

fn end_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, cb) = (a.slot(0), a.slot(1));
    let st = wstate(vm, &this)?;
    if sget(vm, &st, "finished")?.truthy() {
        return Ok(Value::Undefined);
    }
    let fin = getp(vm, &this, "_final")?;
    if fin.truthy() {
        let f = closure(vm, "", 1, final_done, vec![this.clone(), cb]);
        vm.call(&fin, this, &[f])?;
    } else {
        end_finish(vm, &this, &cb)?;
    }
    Ok(Value::Undefined)
}

fn end_finish(vm: &mut Vm, this: &Value, cb: &Value) -> JsResult<()> {
    let st = wstate(vm, this)?;
    sset(vm, &st, "finished", Value::Bool(true))?;
    if cb.truthy() {
        vm.call(cb, Value::Undefined, &[])?;
    }
    emit(vm, this, "finish", &[])?;
    Ok(())
}

fn final_done(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (this, cb) = (a.slot(0), a.slot(1));
    let err = a.arg(0);
    if err.truthy() {
        emit(vm, &this, "error", &[err])?;
    } else {
        end_finish(vm, &this, &cb)?;
    }
    Ok(Value::Undefined)
}

fn writable_cork(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    let c = snum(vm, &st, "corked")?;
    sset(vm, &st, "corked", Value::Num(c + 1.0))?;
    Ok(Value::Undefined)
}

fn writable_uncork(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    if sget(vm, &st, "corked")?.truthy() {
        let c = snum(vm, &st, "corked")?;
        sset(vm, &st, "corked", Value::Num(c - 1.0))?;
    }
    let corked = sget(vm, &st, "corked")?.truthy();
    let cbuf = sget(vm, &st, "corkBuffer")?;
    if !corked && array_len(vm, &cbuf)? > 0.0 {
        let entries = call_method(vm, &cbuf, "splice", &[Value::Num(0.0)])?;
        call_method(vm, &a.this, "_queueBatch", &[entries])?;
    }
    Ok(Value::Undefined)
}

fn writable_destroy(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let st = wstate(vm, &this)?;
    if sget(vm, &st, "destroyed")?.truthy() {
        return Ok(this);
    }
    sset(vm, &st, "destroyed", Value::Bool(true))?;
    let err = a.arg(0);
    if err.truthy() {
        sset(vm, &st, "errored", err.clone())?;
        let rs = getp(vm, &this, "_readableState")?;
        if rs.truthy() {
            sset(vm, &rs, "errored", err.clone())?;
        }
    }
    setp(vm, &this, "writable", Value::Bool(false))?;
    let job = closure(vm, "", 0, destroy_job, vec![this.clone(), err]);
    queue_microtask(vm, job);
    Ok(this)
}

fn writable_length(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    sget(vm, &st, "length")
}

fn writable_hwm(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    sget(vm, &st, "highWaterMark")
}

fn writable_object_mode(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let st = wstate(vm, &a.this)?;
    sget(vm, &st, "objectMode")
}

// --- fs.ReadStream / fs.WriteStream ---

/// normalizeStreamOpts: a string is the encoding, otherwise `options || {}`.
fn normalize_stream_opts(vm: &mut Vm, opts: &Value) -> JsResult<Value> {
    match opts {
        Value::Str(_) => Ok(Value::Obj(vm.obj_from(vec![("encoding", opts.clone())]))),
        v if v.truthy() => Ok(v.clone()),
        _ => Ok(Value::Obj(vm.new_object())),
    }
}

}

fn emit_error_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "error", &[a.slot(1)])?;
    Ok(Value::Undefined)
}

fn emit_close_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    emit(vm, &a.slot(0), "close", &[])?;
    Ok(Value::Undefined)
}

/// open the stream's file (nodeFs.openSync(path, flags, mode)); on failure fd = null and the
/// error is emitted on the next tick. Returns false when opening failed.
fn stream_open(vm: &mut Vm, this: &Value, path: &Value, o: &Value) -> JsResult<bool> {
    let fd = getp(vm, o, "fd")?;
    if !fd.is_nullish() {
        setp(vm, this, "fd", fd)?;
        return Ok(true);
    }
    let flags = getp(vm, this, "flags")?;
    getp(vm, o, "mode")?;
    match open_impl(vm, path, &flags) {
        Ok(n) => {
            setp(vm, this, "fd", n)?;
            Ok(true)
        }
        Err(e) => {
            setp(vm, this, "fd", Value::Null)?;
            let t = closure(vm, "", 0, emit_error_tick, vec![this.clone(), e]);
            next_tick(vm, t)?;
            Ok(false)
        }
    }
}

framed!(read_stream_ctor, ["ReadStream"], read_stream_ctor_);

fn read_stream_ctor_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = instance(vm, a, |c| c.read_stream.clone())?;
    let this = Value::Obj(o.clone());
    let path = a.arg(0);
    let opts = normalize_stream_opts(vm, &a.arg(1))?;
    let enc = getp(vm, &opts, "encoding")?;
    let hwm = getp(vm, &opts, "highWaterMark")?;
    let ropts = Value::Obj(vm.obj_from(vec![("encoding", enc), ("highWaterMark", hwm.clone())]));
    readable_init(vm, &o, &ropts)?;
    setp(vm, &this, "path", path.clone())?;
    let flags = getp(vm, &opts, "flags")?;
    setp(vm, &this, "flags", if flags.truthy() { flags } else { Value::str("r") })?;
    setp(vm, &this, "bytesRead", Value::Num(0.0))?;
    let start = getp(vm, &opts, "start")?;
    setp(vm, &this, "pos", if start.truthy() { start } else { Value::Num(0.0) })?;
    let end = getp(vm, &opts, "end")?;
    setp(vm, &this, "_end", if end.is_nullish() { Value::Num(f64::INFINITY) } else { end })?;
    setp(vm, &this, "_chunk", if hwm.truthy() { hwm } else { Value::Num(65536.0) })?;
    let ac = getp(vm, &opts, "autoClose")?;
    setp(vm, &this, "_autoClose", Value::Bool(!matches!(ac, Value::Bool(false))))?;
    let fd = getp(vm, &opts, "fd")?;
    setp(vm, &this, "_ownFd", Value::Bool(fd.is_nullish()))?;
    if !stream_open(vm, &this, &path, &opts)? {
        return Ok(this);
    }
    let t = closure(vm, "", 0, read_stream_open_tick, vec![this.clone()]);
    next_tick(vm, t)?;
    Ok(this)
}

framed!(read_stream_open_tick, ["<anonymous>"], read_stream_open_tick_);

fn read_stream_open_tick_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let fd = getp(vm, &this, "fd")?;
    if fd.is_nullish() {
        return Ok(Value::Undefined);
    }
    emit(vm, &this, "open", &[fd])?;
    emit(vm, &this, "ready", &[])?;
    call_method(vm, &this, "_pump", &[])?;
    Ok(Value::Undefined)
}

framed!(read_stream_pump, ["_pump"], read_stream_pump_);

fn read_stream_pump_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let r = (|| -> JsResult<()> {
        loop {
            // JS semantics on purpose: `start`/`end` options are used as given
            let pos = getp(vm, &this, "pos")?;
            let end = getp(vm, &this, "_end")?;
            if !vm.op_compare(crate::bytecode::Op::Le, &pos, &end)? {
                break;
            }
            let chunk = getp(vm, &this, "_chunk")?;
            let want = if Value::strict_eq(&end, &Value::Num(f64::INFINITY)) {
                chunk
            } else {
                let diff = vm.op_arith(crate::bytecode::Op::Sub, &end, &pos)?;
                let rest = vm.op_add(&diff, &Value::Num(1.0))?;
                let a = vm.to_number(&chunk)?;
                let b = vm.to_number(&rest)?;
                Value::Num(if a.is_nan() || b.is_nan() { f64::NAN } else { a.min(b) })
            };
            let fd = getp(vm, &this, "fd")?;
            let len = len_arg(vm, &want)?;
            let bytes = pread(vm, &fd, len, pos_arg(&pos))?;
            if bytes.is_empty() {
                break;
            }
            let n = bytes.len() as f64;
            let p = getp(vm, &this, "pos")?;
            let p = vm.op_add(&p, &Value::Num(n))?;
            setp(vm, &this, "pos", p)?;
            let br = getp(vm, &this, "bytesRead")?;
            let br = vm.op_add(&br, &Value::Num(n))?;
            setp(vm, &this, "bytesRead", br)?;
            let buf = new_buffer(vm, bytes)?;
            call_method(vm, &this, "push", &[buf])?;
        }
        call_method(vm, &this, "push", &[Value::Null])?;
        call_method(vm, &this, "_closeStream", &[Value::Null])?;
        Ok(())
    })();
    if let Err(e) = r {
        call_method(vm, &this, "_closeStream", &[e])?;
    }
    Ok(Value::Undefined)
}

fn read_stream_close_stream(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let err = a.arg(0);
    let own = getp(vm, &this, "_ownFd")?.truthy();
    if own && getp(vm, &this, "_autoClose")?.truthy() {
        let fd = getp(vm, &this, "fd")?;
        if !fd.is_nullish() {
            if let Ok(n) = to_num(vm, &fd) {
                close_fd_num(n);
            }
        }
    }
    setp(vm, &this, "fd", Value::Null)?;
    if err.truthy() {
        let t = closure(vm, "", 0, emit_error_tick, vec![this.clone(), err]);
        next_tick(vm, t)?;
    }
    let t = closure(vm, "", 0, emit_close_tick, vec![this]);
    next_tick(vm, t)?;
    Ok(Value::Undefined)
}

fn read_stream_close(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let cb = a.arg(0);
    if cb.truthy() {
        call_method(vm, &this, "once", &[Value::str("close"), cb])?;
    }
    let fd = getp(vm, &this, "fd")?;
    if !fd.is_nullish() && getp(vm, &this, "_ownFd")?.truthy() {
        if let Ok(n) = to_num(vm, &fd) {
            close_fd_num(n);
        }
        setp(vm, &this, "fd", Value::Null)?;
    }
    Ok(Value::Undefined)
}

framed!(write_stream_ctor, ["WriteStream"], write_stream_ctor_);

fn write_stream_ctor_(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = instance(vm, a, |c| c.write_stream.clone())?;
    let this = Value::Obj(o.clone());
    let path = a.arg(0);
    let opts = normalize_stream_opts(vm, &a.arg(1))?;
    let empty = Value::Obj(vm.new_object());
    writable_init(vm, &o, &empty)?;
    setp(vm, &this, "path", path.clone())?;
    let flags = getp(vm, &opts, "flags")?;
    setp(vm, &this, "flags", if flags.truthy() { flags } else { Value::str("w") })?;
    setp(vm, &this, "bytesWritten", Value::Num(0.0))?;
    let start = getp(vm, &opts, "start")?;
    setp(vm, &this, "pos", start)?;
    let enc = getp(vm, &opts, "encoding")?;
    setp(vm, &this, "_encoding", if enc.truthy() { enc } else { Value::str("utf8") })?;
    let ac = getp(vm, &opts, "autoClose")?;
    setp(vm, &this, "_autoClose", Value::Bool(!matches!(ac, Value::Bool(false))))?;
    let fd = getp(vm, &opts, "fd")?;
    setp(vm, &this, "_ownFd", Value::Bool(fd.is_nullish()))?;
    if !stream_open(vm, &this, &path, &opts)? {
        return Ok(this);
    }
    let onfinish = closure(vm, "", 0, write_stream_on_finish, vec![this.clone()]);
    call_method(vm, &this, "on", &[Value::str("finish"), onfinish])?;
    let t = closure(vm, "", 0, write_stream_open_tick, vec![this.clone()]);
    next_tick(vm, t)?;
    Ok(this)
}

fn write_stream_on_finish(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    if getp(vm, &this, "_autoClose")?.truthy() {
        let t = closure(vm, "", 0, emit_close_tick, vec![this]);
        next_tick(vm, t)?;
    }
    Ok(Value::Undefined)
}

fn write_stream_open_tick(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.slot(0);
    let fd = getp(vm, &this, "fd")?;
    if fd.is_nullish() {
        return Ok(Value::Undefined);
    }
    emit(vm, &this, "open", &[fd])?;
    emit(vm, &this, "ready", &[])?;
    Ok(Value::Undefined)
}

fn write_stream_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let (chunk, enc, cb) = (a.arg(0), a.arg(1), a.arg(2));
    let r = (|| -> JsResult<()> {
        let e = if enc.truthy() { enc.clone() } else { getp(vm, &this, "_encoding")? };
        let buf = to_buffer(vm, &chunk, &e)?;
        let posv = getp(vm, &this, "pos")?;
        let pos = pos_arg(&posv);
        let fd = getp(vm, &this, "fd")?;
        let n = pwrite(vm, &fd, &buf, pos)? as f64;
        let bw = getp(vm, &this, "bytesWritten")?;
        let bw = vm.op_add(&bw, &Value::Num(n))?;
        setp(vm, &this, "bytesWritten", bw)?;
        if !posv.is_nullish() {
            let p = getp(vm, &this, "pos")?;
            let p = vm.op_add(&p, &Value::Num(n))?;
            setp(vm, &this, "pos", p)?;
        }
        vm.call(&cb, Value::Undefined, &[])?;
        Ok(())
    })();
    if let Err(e) = r {
        vm.call(&cb, Value::Undefined, &[e])?;
    }
    Ok(Value::Undefined)
}

fn write_stream_final(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let cb = a.arg(0);
    let own = getp(vm, &this, "_ownFd")?.truthy() && getp(vm, &this, "_autoClose")?.truthy();
    let fd = getp(vm, &this, "fd")?;
    if own && !fd.is_nullish() {
        let r = (|| -> JsResult<()> {
            let n = vm.to_number(&fd)?;
            close_fd_num(n);
            setp(vm, &this, "fd", Value::Null)?;
            vm.call(&cb, Value::Undefined, &[])?;
            Ok(())
        })();
        if let Err(e) = r {
            vm.call(&cb, Value::Undefined, &[e])?;
        }
    } else {
        vm.call(&cb, Value::Undefined, &[])?;
    }
    Ok(Value::Undefined)
}

fn write_stream_close(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    let cb = a.arg(0);
    if cb.truthy() {
        call_method(vm, &this, "once", &[Value::str("close"), cb])?;
    }
    call_method(vm, &this, "end", &[])?;
    Ok(Value::Undefined)
}

// ============================================================================================
// module assembly
// ============================================================================================

/// Present a native as an ordinary `function` (the reference defines these as function
/// expressions): it gets a `prototype` object and `new f(...)` yields an object.
fn plain_function(vm: &mut Vm, inner: Obj) -> Obj {
    let (name, len) = {
        let b = inner.borrow();
        let n = match b.props.get(&vm.intr.key_name) {
            Some(Prop::Data { value: Value::Str(s), .. }) => s.to_rust_string(),
            _ => String::new(),
        };
        let l = match b.props.get(&vm.intr.key_length) {
            Some(Prop::Data { value: Value::Num(n), .. }) => *n as u32,
            _ => 0,
        };
        (n, l)
    };
    let outer = vm.native_closure(&name, len, plain_function_shim, vec![Value::Obj(inner)]);
    vm.make_ctor(&outer);
    let proto = vm.new_object();
    proto.set_prop(key("constructor"), Value::Obj(outer.clone()), WC);
    outer.set_prop(key("prototype"), Value::Obj(proto), WRITABLE);
    outer
}

fn plain_function_shim(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let inner = a.slot(0);
    match &a.new_target {
        None => vm.call(&inner, a.this.clone(), a.args),
        Some(nt) => {
            let fb = vm.intr.object_proto.clone();
            let proto = vm.proto_from_nt(&Some(nt.clone()), &fb)?;
            let obj = Value::Obj(Obj::new(Some(proto), ObjKind::Ordinary));
            let r = vm.call(&inner, obj.clone(), a.args)?;
            Ok(if r.is_object() { r } else { obj })
        }
    }
}

fn make_class(vm: &mut Vm, name: &str, len: u32, ctor: NativeFn, parent: Option<Obj>) -> (Obj, Obj) {
    let proto = Obj::new(Some(parent.unwrap_or_else(|| vm.intr.object_proto.clone())), ObjKind::Ordinary);
    let c = vm.native_ctor(name, len, ctor, &proto);
    (c, proto)
}

struct Built {
    stats: Obj,
    dirent: Obj,
    dir: Obj,
    stat_watcher: Obj,
    read_stream: Obj,
    write_stream: Obj,
    file_handle: Obj,
}

fn setup_classes(vm: &mut Vm) -> JsResult<Built> {
    let ee = crate::runtime::node::builtin_module(vm, "events")?.unwrap_or(Value::Undefined);
    let ee_ctor = ee.as_obj().cloned();
    let ee_proto = match &ee {
        Value::Obj(_) => getp(vm, &ee, "prototype")?.as_obj().cloned(),
        _ => None,
    };

    let (stats, sp) = make_class(vm, "Stats", 1, stats_ctor, None);
    install_kind_methods(vm, &sp);
    let (dirent, dp) = make_class(vm, "Dirent", 3, dirent_ctor, None);
    install_kind_methods(vm, &dp);

    let (dir, dirp) = make_class(vm, "Dir", 2, dir_ctor, None);
    vm.def_method(&dirp, "readSync", 0, dir_read_sync);
    vm.def_method(&dirp, "read", 1, dir_read);
    vm.def_method(&dirp, "closeSync", 0, dir_close_sync);
    vm.def_method(&dirp, "close", 1, dir_close);
    let sai = vm.intr.sym_async_iterator.clone();
    vm.def_sym_method(&dirp, &sai, "[Symbol.asyncIterator]", 0, dir_async_iter);

    let (stat_watcher, swp) = make_class(vm, "StatWatcher", 0, stat_watcher_ctor, ee_proto.clone());
    if let Some(ec) = &ee_ctor {
        stat_watcher.borrow_mut().proto = Some(ec.clone());
    }
    vm.def_method(&swp, "start", 0, |_vm, _a| Ok(Value::Undefined));
    vm.def_method(&swp, "stop", 0, |_vm, _a| Ok(Value::Undefined));
    vm.def_method(&swp, "ref", 0, return_this);
    vm.def_method(&swp, "unref", 0, return_this);

    // internal stream bases: Stream (empty, extends EventEmitter) → Readable / Writable
    let (stream, sbp) = make_class(vm, "Stream", 0, stream_ctor, ee_proto.clone());
    if let Some(ec) = &ee_ctor {
        stream.borrow_mut().proto = Some(ec.clone());
    }
    let (readable, rp) = make_class(vm, "Readable", 0, readable_ctor, Some(sbp.clone()));
    readable.borrow_mut().proto = Some(stream.clone());
    vm.def_method(&rp, "_read", 0, |_vm, _a| Ok(Value::Undefined));
    vm.def_getter(&rp, "readableLength", readable_length);
    vm.def_getter(&rp, "readableHighWaterMark", readable_hwm);
    vm.def_getter(&rp, "readableObjectMode", readable_object_mode);
    let rmethods: &[(&str, u32, NativeFn)] = &[
        ("push", 1, readable_push),
        ("read", 1, readable_read),
        ("setEncoding", 1, readable_set_encoding),
        ("on", 2, readable_on),
        ("addListener", 2, readable_add_listener),
        ("once", 2, readable_once),
        ("resume", 0, readable_resume),
        ("pause", 0, readable_pause),
        ("isPaused", 0, readable_is_paused),
        ("pipe", 1, readable_pipe),
        ("unpipe", 0, readable_unpipe),
        ("destroy", 1, readable_destroy),
    ];
    for (n, l, f) in rmethods {
        vm.def_method(&rp, n, *l, *f);
    }
    vm.def_sym_method(&rp, &sai, "[Symbol.asyncIterator]", 0, readable_async_iterator);

    let (writable, wp) = make_class(vm, "Writable", 0, writable_ctor, Some(sbp));
    writable.borrow_mut().proto = Some(stream);
    let wmethods: &[(&str, u32, NativeFn)] = &[
        ("_write", 3, writable_default_write),
        ("write", 3, writable_write),
        ("_queueBatch", 1, writable_queue_batch),
        ("end", 3, writable_end),
        ("cork", 0, writable_cork),
        ("uncork", 0, writable_uncork),
        ("setDefaultEncoding", 0, return_this),
    ];
    for (n, l, f) in wmethods {
        vm.def_method(&wp, n, *l, *f);
    }
    vm.def_getter(&wp, "writableLength", writable_length);
    vm.def_getter(&wp, "writableHighWaterMark", writable_hwm);
    vm.def_getter(&wp, "writableObjectMode", writable_object_mode);
    vm.def_method(&wp, "destroy", 1, writable_destroy);

    let (read_stream, rsp) = make_class(vm, "ReadStream", 2, read_stream_ctor, Some(rp));
    read_stream.borrow_mut().proto = Some(readable.clone());
    vm.def_method(&rsp, "_pump", 0, read_stream_pump);
    vm.def_method(&rsp, "_closeStream", 1, read_stream_close_stream);
    vm.def_method(&rsp, "close", 1, read_stream_close);

    let (write_stream, wsp) = make_class(vm, "WriteStream", 2, write_stream_ctor, Some(wp));
    write_stream.borrow_mut().proto = Some(writable.clone());
    vm.def_method(&wsp, "_write", 3, write_stream_write);
    vm.def_method(&wsp, "_final", 1, write_stream_final);
    vm.def_method(&wsp, "close", 1, write_stream_close);

    let (file_handle, fhp) = make_class(vm, "FileHandle", 1, file_handle_ctor, None);
    let fmethods: &[(&str, u32, NativeFn)] = &[
        ("read", 4, fh_read),
        ("write", 4, fh_write),
        ("readv", 2, fh_readv),
        ("writev", 2, fh_writev),
        ("readFile", 1, fh_read_file),
        ("writeFile", 2, fh_write_file),
        ("appendFile", 2, fh_append_file),
        ("chmod", 1, fh_chmod),
        ("chown", 2, fh_chown),
        ("stat", 1, fh_stat),
        ("truncate", 1, fh_truncate),
        ("utimes", 2, fh_utimes),
        ("sync", 0, fh_sync),
        ("datasync", 0, fh_datasync),
        ("close", 0, fh_close),
        ("createReadStream", 1, fh_create_read_stream),
        ("createWriteStream", 1, fh_create_write_stream),
    ];
    for (n, l, f) in fmethods {
        vm.def_method(&fhp, n, *l, *f);
    }
    let sad = vm.intr.sym_async_dispose.clone();
    vm.def_sym_method(&fhp, &sad, "[Symbol.asyncDispose]", 0, fh_async_dispose);

    // async iterator objects (fs.promises.glob / Dir iteration) stand in for async generator
    // objects: an empty per-"generator function" prototype over the shared next/return/throw
    let lip = Obj::new(Some(vm.intr.async_generator_proto.clone()), ObjKind::Ordinary);
    vm.def_method(&lip, "next", 1, list_iter_next);
    vm.def_method(&lip, "return", 1, list_iter_return);
    vm.def_method(&lip, "throw", 1, list_iter_throw);
    let glob_iter = Obj::new(Some(lip.clone()), ObjKind::Ordinary);
    let dir_iter = Obj::new(Some(lip), ObjKind::Ordinary);

    FS.with(|s| {
        let c = &mut s.borrow_mut().classes;
        c.stats = Some(sp);
        c.dirent = Some(dp);
        c.dir = Some(dirp);
        c.file_handle = Some(fhp);
        c.read_stream = Some(rsp);
        c.write_stream = Some(wsp);
        c.stat_watcher = Some(swp);
        c.ee_proto = ee_proto;
        c.list_iter = Some(glob_iter);
        c.dir_iter = Some(dir_iter);
        c.readable_ctor = Some(readable);
        c.writable_ctor = Some(writable);
    });
    Ok(Built { stats, dirent, dir, stat_watcher, read_stream, write_stream, file_handle })
}

