// print name/length of functions reachable from module exports (1 level + prototypes)
const name = process.argv[2];
const m = require(name);
function fl(f) { return JSON.stringify(f.name) + '/' + f.length; }
function desc(o, k) {
  const d = Object.getOwnPropertyDescriptor(o, k);
  if (!d) return '?';
  let s = (d.enumerable ? 'e' : '-') + (d.writable ? 'w' : (d.get || d.set ? 'a' : '-')) + (d.configurable ? 'c' : '-');
  if (d.get) s += ' get' + fl(d.get);
  if (d.set) s += ' set' + fl(d.set);
  if (typeof d.value === 'function') s += ' fn' + fl(d.value) + (d.value.prototype ? '+proto' : '');
  else if (!d.get && !d.set) { let v; try { v = JSON.stringify(d.value); } catch (e) { v = String(d.value); } s += ' ' + (typeof d.value) + ' ' + (v && v.length > 80 ? v.slice(0, 80) + '...' : v); }
  return s;
}
console.log('module', typeof m, typeof m === 'function' ? fl(m) : '');
for (const k of Object.getOwnPropertyNames(m)) {
  console.log(k, desc(m, k));
  const v = m[k];
  if (typeof v === 'function' && v.prototype && k[0] === k[0].toUpperCase()) {
    console.log('  proto chain:', Object.getPrototypeOf(v.prototype) && Object.getPrototypeOf(v.prototype).constructor && Object.getPrototypeOf(v.prototype).constructor.name);
    for (const pk of Object.getOwnPropertyNames(v.prototype)) console.log('  .' + pk, desc(v.prototype, pk));
    for (const sk of Object.getOwnPropertyNames(v)) if (!['length', 'name', 'prototype'].includes(sk)) console.log('  static ' + sk, desc(v, sk));
    for (const sk of Object.getOwnPropertySymbols(v.prototype)) console.log('  sym ' + String(sk), desc(v.prototype, sk));
  }
}
for (const s of Object.getOwnPropertySymbols(m)) console.log('sym', String(s), desc(m, s));

