                ObjKind::Native(n) => K::Native(n.f),
                ObjKind::Bound(bf) => K::Bound(bf.target.clone(), bf.args.clone()),
                ObjKind::Proxy(_) => K::Proxy,

fn require_new(vm: &mut Vm, a: &Args) -> JsResult<Obj> {
    match &a.new_target {
