        match job {
            Job::Reaction(r, arg) => crate::builtins::promise::run_reaction(self, r, arg),
            Job::ResolveThenable(p, thenable, then) => crate::builtins::promise::run_resolve_thenable(self, p, thenable, then),
            Job::Callback(f, args) => {
