const { Readable, Writable, Transform, PassThrough, Duplex, pipeline, finished } = require('stream');
const sp = require('stream/promises');
const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));

async function main() {
  // async iteration over Readable.from
  const out = [];
  for await (const c of Readable.from(['a', 'b', 'c'])) out.push(c);
  log('iter', out);

  // pipeline with transform and writable
  const got = [];
  await sp.pipeline(
    Readable.from(['x', 'y', 'z']),
    new Transform({ transform(c, e, cb) { cb(null, String(c) + '!'); } }),
    new Writable({ write(c, e, cb) { got.push(String(c)); cb(); } })
  );
  log('pipeline done', got);

  // pipeline with async generator
  const got2 = [];
  await sp.pipeline(
    Readable.from([1, 2, 3], { objectMode: true }),
    async function* (src) { for await (const x of src) yield x * 2; },
    new Writable({ objectMode: true, write(c, e, cb) { got2.push(c); cb(); } })
  );
  log('pipeline gen', got2);

  // pipeline callback with error
  await new Promise((resolve) => {
    pipeline(
      Readable.from(['q']),
      new Transform({ transform(c, e, cb) { cb(new Error('boom')); } }),
      new PassThrough(),
      (err) => { log('pipeline cb', err && err.message); resolve(); }
    );
  });

  // finished
  const pt = new PassThrough();
  finished(pt, (err) => log('finished pt', err));
  pt.resume();
  pt.end('data');
  await new Promise(r => setTimeout(r, 10));

  // sp.finished
  const r2 = Readable.from(['1', '2']);
  r2.resume();
  await sp.finished(r2);
  log('sp.finished ok');

  // destroy with error
  const r3 = new Readable();
  r3.on('error', e => log('r3 error', e.message));
  r3.on('close', () => log('r3 close'));
  r3.destroy(new Error('kaboom'));
  log('destroyed', r3.destroyed, r3.readable, r3._readableState.destroyed);
  await new Promise(r => setTimeout(r, 10));

  // objectMode and highWaterMark backpressure
  const w = new Writable({ highWaterMark: 2, objectMode: true, write(c, e, cb) { setTimeout(cb, 1); } });
  log('w1', w.write({ a: 1 }), w.writableLength);
  log('w2', w.write({ a: 2 }), w.writableLength);
  w.on('drain', () => log('drain', w.writableLength));
  await new Promise(r => setTimeout(r, 30));

  // read() paused mode
  const r4 = new Readable();
  r4.push('abc');
  r4.push('def');
  log('read', String(r4.read(2)), String(r4.read()), r4.read());
  r4.push(null);
  r4.on('end', () => log('r4 end'));
  log('read after end', r4.read());
  await new Promise(r => setTimeout(r, 10));
  log('done');
}
main().catch(e => log('main err', e.message));

