244	/// Reap exited children and report exits (in spawn order) whose stdio has been drained — or
245	/// that have waited a full reaper tick for it (a grandchild may keep the pipes open).
246	fn poll_children(vm: &mut Vm) {
247	    let tick = TICKS.with(|t| t.get());
248	    let exited: Vec<(Value, Option<i32>)> = CHILDREN.with(|c| {
249	        let mut out = Vec::new();
250	        for (_, e) in c.borrow_mut().iter_mut() {
251	            if let Some(ch) = e.child.as_mut() {
252	                match ch.try_wait() {
253	                    Ok(Some(status)) => {
254	                        e.child = None;
255	                        e.exit = Some(status.code());
256	                        e.exit_tick = tick;
257	                    }
258	                    Ok(None) => {}
259	                    Err(_) => {
260	                        e.child = None;
261	                        e.exit = Some(None);
262	                        e.exit_tick = tick;
263	                    }
264	                }
265	            }
266	            if let Some(code) = e.exit {
267	                if e.eofs >= e.expected_eofs || tick > e.exit_tick {
268	                    e.exit = None;
269	                    out.push((std::mem::replace(&mut e.wait_resolve, Value::Undefined), code));
270	                }
271	            }
272	        }
273	        out
274	    });
275	    for (resolve, code) in exited {
276	        if resolve.is_callable() {
277	            let c = match code {
278	                Some(c) => Value::Num(c as f64),
279	                None => Value::Null,
280	            };
281	            if let Err(e) = vm.call(&resolve, Value::Undefined, &[c]) {
282	                crate::runtime::report_uncaught(vm, &e);
283	            }
284	        }
285	    }
286	}
