292	/// Keep a 20 ms idle tick running while children are alive (the loop's reaper poll).
293	fn ensure_ticker(vm: &mut Vm) {
294	    if TICKER.with(|t| t.get()) || !any_alive() {
295	        return;
296	    }
297	    TICKER.with(|t| t.set(true));
298	    crate::runtime::spawn_op(
299	        vm,
300	        || std::thread::sleep(std::time::Duration::from_millis(REAP_TICK_MS)),
301	        |vm: &mut Vm, _: ()| {
302	            TICKER.with(|t| t.set(false));
303	            TICKS.with(|t| t.set(t.get() + 1));
304	            poll_children(vm);
305	            ensure_ticker(vm);
306	        },
307	    );
308	}
