const server = http.createServer((req, res) => {
  console.log('req', req.method, req.url, JSON.stringify(req.headers), JSON.stringify(req.rawHeaders));
  if (req.url === '/plain') { res.end('plain text'); return; }
  if (req.url === '/multi') {
    res.setHeader('Set-Cookie', ['a=1', 'b=2']);
    res.setHeader('X-Num', 42);
    res.statusCode = 404;
    res.statusMessage = 'Nope';
    res.write('part1 ');
    res.write(Buffer.from('part2'));
    res.end();
    return;
  }
  if (req.url === '/empty') { res.writeHead(204); res.end(); return; }
  if (req.url === '/close') { res.end('bye'); server.close(); return; }
  res.end();
});
server.listen(Number(process.argv[2] || 18080), () => console.log('listening'));

