const http = require('http');
const port = Number(process.argv[2]);
const which = process.argv[3] || 'get';
function show(res) {
  console.log('status', res.statusCode, JSON.stringify(res.statusMessage), res.httpVersion, JSON.stringify(res.headers), JSON.stringify(res.rawHeaders));
  let d = '';
  res.on('data', c => { d += c; console.log('chunk', typeof c, c.length); });
  res.on('end', () => console.log('end', JSON.stringify(d), res.complete));
}
if (which === 'get') {
  const r = http.get(`http://127.0.0.1:${port}/path?q=1`, show);
  r.on('close', () => console.log('req close'));
  r.on('finish', () => console.log('req finish'));
} else if (which === 'post') {
  const r = http.request({ host: '127.0.0.1', port, method: 'POST', path: '/p', headers: { 'X-Foo': 'Bar', 'Content-Type': 'application/json' } }, show);
  r.write(JSON.stringify({ a: 1 }));
  r.end();
} else if (which === 'headers') {
  const r = http.request(`http://127.0.0.1:${port}/h`, { method: 'PUT', headers: { 'Content-Length': 3, 'b-header': ['x', 'y'], 'A-Header': 'z' } }, show);
  r.end('abc');
} else if (which === 'head') {
  http.request({ host: '127.0.0.1', port, method: 'HEAD' }, show).end();
} else if (which === 'auth') {
  http.get({ host: '127.0.0.1', port, auth: 'user:pass', path: '/auth' }, show);
}

