const http = require('http');
const https = require('https');
const show = (label) => (e) => console.log(label, e.name, JSON.stringify(e.message), e.code, JSON.stringify(Object.keys(e)), e.cause && e.cause.message);
http.get('http://127.0.0.1:1/', () => console.log('resp?')).on('error', show('refused'));
http.get('http://nonexistent.invalid/', () => console.log('resp?')).on('error', show('dns'));
https.get('https://127.0.0.1:1/', () => console.log('resp?')).on('error', show('https'));
try { http.get('not a url', () => {}).on('error', show('badurl')); } catch (e) { show('badurl-throw')(e); }
