r.on('error', show('aborted'));
r.on('abort', () => console.log('abort event'));
r.on('close', () => console.log('close event'));
r.abort();
console.log(http.STATUS_CODES[404], http.STATUS_CODES[418], Object.keys(http.STATUS_CODES).length, http.METHODS.length, http.METHODS.slice(0, 5).join(','));
console.log(http.maxHeaderSize, typeof http.globalAgent, http.globalAgent instanceof http.Agent);
try { http.validateHeaderName('bad name'); } catch (e) { show('vhn')(e); }
try { http.validateHeaderValue('x', undefined); } catch (e) { show('vhv')(e); }
try { http.validateHeaderValue('x', 'a\nb'); } catch (e) { show('vhv2')(e); }
const agent = new http.Agent({ keepAlive: true, maxSockets: 5 });
console.log(JSON.stringify(agent.options), agent.maxSockets, agent.maxFreeSockets, agent.keepAlive, agent.protocol, agent.getName());
try { agent.createConnection(); } catch (e) { show('cc')(e); }
try { http._connectionListener(); } catch (e) { show('cl')(e); }

