const http = require('http');
const server = http.createServer();
console.log('addr before', server.address(), server.listening, JSON.stringify(Object.keys(server)));
server.on('request', (req, res) => {
  console.log('req keys', JSON.stringify(Object.keys(req)));
  console.log('req fields', req.httpVersionMajor, req.httpVersionMinor, req.complete, req.aborted, JSON.stringify(req.trailers), typeof req.socket.remotePort, req.socket.remoteAddress, req.socket.encrypted, req.connection === req.socket);
  console.log('res keys', JSON.stringify(Object.keys(res)));
  console.log('res fields', res.statusCode, res.statusMessage, res.headersSent, res.finished, res.sendDate, res.req === req);
  res.setHeader('A', '1');
  console.log('getHeader', res.getHeader('a'), res.hasHeader('A'), JSON.stringify(res.getHeaderNames()), JSON.stringify(res.getHeaders()));
  res.appendHeader('A', '2');
  console.log('after append', JSON.stringify(res.getHeader('a')));
  res.removeHeader('a');
  console.log('after remove', res.hasHeader('a'));
  res.writeHead(200, 'Fine', ['X-Arr', 'v']);
  console.log('headersSent', res.headersSent);
  try { res.setHeader('late', 'x'); } catch (e) { console.log('late setHeader', e.name, e.message, e.code); }
  res.end('done', () => console.log('end cb'));
  res.on('finish', () => console.log('res finish', res.finished));
  res.on('close', () => console.log('res close'));
  req.on('end', () => console.log('req end', req.complete));
  req.on('close', () => console.log('req close'));
  req.resume();
});
server.on('listening', () => console.log('listening event'));
server.on('close', () => console.log('close event'));
server.listen(0, () => {
  const a = server.address();
  console.log('addr', a.address, a.family, typeof a.port, server.listening);
  http.get({ port: a.port, host: 'localhost' }, (res) => {
    console.log('client status', res.statusCode, res.statusMessage, JSON.stringify(res.headers));
    res.resume();
    res.on('end', () => {
      server.close((err) => console.log('close cb', err));
      console.log('after close call', server.listening, server.address() && 'has addr');
    });
  });
});

