const http = require('http');
const server = http.createServer((req, res) => {
  if (req.url === '/order') {
    res.setHeader('Z-Last', 'z');
    res.setHeader('A-First', 'a');
    res.setHeader('M-Mid', ['m1', 'm2']);
    res.setHeader('X-Case', '1');
    res.setHeader('x-case', '2');
    res.end('ok');
  } else if (req.url === '/cl') {
    res.setHeader('Content-Length', '2');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('Server', 'custom');
    res.setHeader('Date', 'today');
    res.end('ok');
  } else if (req.url === '/ct') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.write('<h1>');
    res.end('hi</h1>');
  } else if (req.url === '/json') {
    res.statusCode = 500;
    res.end(JSON.stringify({ e: 1 }));
  } else if (req.url === '/unknown-status') {
    res.writeHead(299);
    res.end();
  } else if (req.url === '/nobody') {
    res.end();
  } else if (req.url === '/binary') {
    res.end(Buffer.from([0, 1, 2, 255]));
  } else if (req.url === '/chunked-req') {
    let b = '';
    req.on('data', d => b += d);
    req.on('end', () => res.end('got:' + b + ':' + JSON.stringify(req.headers)));
  } else {
    res.writeHead(302, { Location: '/elsewhere' });
    res.end();
  }
});
server.listen(Number(process.argv[2] || 18081));

