  return new Promise((resolve, reject) => {
    http.get({ port: server.address().port, path }, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => resolve({ status: res.statusCode, type: res.headers['content-type'], data }));
    }).on('error', reject);
  });
}
