  return new Promise((resolve, reject) => {
    const body = JSON.stringify(obj);
    const req = http.request({ port: server.address().port, path, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, (res) => {
