const log = (...a) => console.log(a.map(x => typeof x === 'string' ? x : JSON.stringify(x)).join(' '));
const step = process.argv[2] || 'a';
if (step === 'a') {
  // server does not end on 'end' (allowHalfOpen false)
  const server = net.createServer((sock) => {
    sock.on('end', () => log('S end'));
    sock.on('finish', () => log('S finish'));
    sock.on('close', (h) => { log('S close', h); server.close(); });
  });
  server.listen(0, () => {
    const c = net.connect({ port: server.address().port }, () => { log('C connected'); c.end('bye'); });
    c.on('end', () => log('C end'));
    c.on('finish', () => log('C finish'));
    c.on('close', (h) => log('C close', h));
  });
} else if (step === 'b') {
  const c = net.connect(1, '127.0.0.1');
  c.on('error', (e) => log('C error', e.name, e.message, e.code, e.errno, e.syscall, e.address, e.port, JSON.stringify(Object.keys(e))));
  c.on('close', (h) => log('C close', h));
} else if (step === 'c') {
  const server = net.createServer((sock) => {
    sock.setEncoding('utf8');
    sock.on('data', (d) => { log('S data', typeof d, d); });
    sock.on('close', () => { log('S close'); });
  });
  server.listen(0, () => {
    const c = net.createConnection(server.address().port);
    c.on('connect', () => {
      log('C address', JSON.stringify(Object.keys(c.address())), c.address().family);
      c.write('one');
      c.write(Buffer.from('two'), () => log('write cb'));
      server.getConnections((err, n) => log('connections', err, n));
      setTimeout(() => { c.destroy(); log('destroyed', c.destroyed, c.readyState); }, 50);
    });
    c.on('close', (h) => { log('C close', h); server.close(() => log('server closed')); });
  });
} else if (step === 'd') {
  const c = new net.Socket();
  c.on('error', (e) => log('error', e.message));
  c.write('x', (err) => log('write cb', err && err.message));
