  server.listen(0, () => {
    const c = net.connect(server.address().port, () => {
      setTimeout(() => {
        c.write('after reset', (err) => log('write cb', err && err.message, err && err.code));
      }, 100);
    });
    c.on('error', (e) => log('error', e.message, e.code, JSON.stringify(Object.keys(e))));
    c.on('end', () => log('end'));
    c.on('close', (h) => { log('close', h); server.close(); });
  });
