async function main() {
  // break out of for-await
  const r = Readable.from([1, 2, 3, 4], { objectMode: true });
  r.on('close', () => log('r close'));
  for await (const x of r) { log('x', x); if (x === 2) break; }
  log('after break', r.destroyed, r._readableState.destroyed);

  // async generator source → transform generator → sink
  async function* src() { for (let i = 0; i < 3; i++) yield 'line' + i; }
  async function* upper(source) { for await (const s of source) yield String(s).toUpperCase(); }
  const got = [];
  await pp(src(), upper, new Writable({ write(c, e, cb) { got.push(String(c)); cb(); } }));
  log('pp result', got);

  // pipeline ending in async function
  const res = await pp(Readable.from(['a', 'b']), async function (source) { let s = ''; for await (const c of source) s += c; return s; });
  log('pp fn result', res);

  // error inside generator
  async function* bad() { yield 1; throw new Error('gen error'); }
  try { await pp(bad(), new PassThrough({ objectMode: true }), new Writable({ objectMode: true, write(c, e, cb) { cb(); } })); } catch (e) { log('pp error', e.message); }

  // finished on writable
  const w = new Writable({ write(c, e, cb) { setTimeout(cb, 1); } });
  w.write('a');
  w.end();
  await pf(w);
  log('pf done', w.writableFinished, w._writableState.finished);

  // pipeline callback form with error from destination
  await new Promise((resolve) => {
    pipeline(Readable.from(['z']), new Writable({ write(c, e, cb) { cb(new Error('dest fail')); } }), (err) => { log('cb err', err && err.message); resolve(); });
  });

  // stream.promises.finished with readable that errors
  const er = new Readable({ read() {} });
  setTimeout(() => er.destroy(new Error('boom')), 1);
  try { await pf(er); } catch (e) { log('pf error', e.message); }

  log('end of main');
}
main().catch(e => log('main err', e && e.message));

