const { once } = require('events');
const util = require('util');
async function main() {
  const child = spawn('sh', ['-c', 'echo out; exit 2']);
  let out = '';
  child.stdout.on('data', d => out += d);
  const [code, signal] = await once(child, 'close');
  console.log('closed', code, signal, JSON.stringify(out));
  const execP = util.promisify(exec);
  const r = await execP('echo promisified');
  console.log('exec promisified', JSON.stringify(r));
  const execFileP = util.promisify(execFile);
  const r2 = await execFileP('echo', ['a']);
  console.log('execFile promisified', JSON.stringify(r2));
  try { await execP('exit 3'); } catch (e) { console.log('rejected', e.message, e.code); }
  for (const cmd of ['echo one', 'echo two', 'echo three']) {
