const which = process.argv[2];
const net = require('net');
if (which === 'connect') {
  const s = net.createServer((sock) => sock.end());
  s.listen(0, () => {
    const c = net.connect(s.address().port, () => { s.close(); throw new Error('thrown in connect cb'); });
    c.on('close', () => console.log('client close'));
  });
} else if (which === 'connection') {
  const s = net.createServer((sock) => { throw new Error('thrown in connection'); });
  s.listen(0, () => {
    const c = net.connect(s.address().port);
    c.on('close', () => { console.log('client close'); s.close(); });
    setTimeout(() => { console.log('timer'); c.destroy(); }, 50);
  });
} else if (which === 'dgram') {
  const d = require('dgram').createSocket('udp4');
  d.on('message', () => { d.close(); throw new Error('thrown in message'); });
  d.bind(0, '127.0.0.1', () => d.send('x', d.address().port, '127.0.0.1'));
} else if (which === 'rlfrom') {
  const { Readable } = require('stream');
  const rl = require('readline').createInterface({ input: Readable.from(['a\nb\n']) });
  rl.on('line', (l) => { throw new Error('line ' + l); });
  rl.on('close', () => console.log('closed'));
}

